void handle_syscall_entry(void *data, struct pt_regs *regs, long id) {
    struct ftrace_event_file *file;
    struct trace_entry *entry;
    struct ring_buffer *buffer;
    unsigned long flags;
    int pc;

    if (!current || !current->tracing)
        return;

    id = (long)get_syscall_number(current, regs);
    if (id < 0)
        return;

    file = find_event_file(TRACE_SYSTEM_RAW, syscall_event_names[id]);
    if (!file || !file->enabled)
        return;

    buffer = file->ring_buffer;
    if (!buffer)
        return;

    flags = raw_local_save_flags();
    pc = preempt_count();

    entry = __trace_buffer_lock_reserve(buffer, sizeof(*entry), flags, pc, 0);
    if (!entry)
        return;

    entry->type = TRACE_SYSCALL_ENTRY;
    entry->syscall_id = id;
    memcpy(&entry->data, regs, sizeof(*regs));

    __trace_buffer_commit(buffer, entry);
}

void handle_syscall_entry(void *data, struct pt_regs *regs, long id)
{
    int syscall_nr = regs->syscallno;

    if (syscall_nr < 0)
        return;

    struct ftrace_event_file *event_file = get_syscall_event_file(syscall_nr);
    if (!event_file || !event_file->enabled)
        return;

    struct trace_entry *entry;
    struct ring_buffer *buffer = event_file->buffer;
    unsigned long flags = 0;
    unsigned int preemption = 0;

    raw_local_save_flags(flags);
    preemption = current_thread_info()->preempt_count;

    entry = __trace_buffer_lock_reserve(buffer, TRACE_SYSCALL_ENTRY, sizeof(*entry));
    if (!entry)
        return;

    entry->type = TRACE_SYSCALL_ENTRY;
    entry->pid = current->pid;
    entry->syscall_nr = syscall_nr;
    *(unsigned long *)entry->data = id;

    trace_buffer_commit(buffer, entry);
}

void handle_syscall_entry(void *data, struct pt_regs *regs, long id) {
    int syscall_num = regs->syscall;
    struct ftrace_event_file *file;

    if (syscall_num < 0 || syscall_num >= __NR_syscalls)
        return;

    file = get_syscall_event_file(syscall_num);
    if (!file || !file->enabled)
        return;

    struct trace_entry *entry;
    struct ftrace_raw_syscall *raw_entry;
    unsigned long flags, preemption;

    raw_local_save_flags(flags);
    preemption = preempt_count();

    entry = trace_buffer_reserve(data, file->event, sizeof(*raw_entry));
    if (!entry)
        return;

    raw_entry = (struct ftrace_raw_syscall *)entry->data;
    raw_entry->nr = syscall_num;
    raw_entry->args[0] = regs->regs[0];
    raw_entry->args[1] = regs->regs[1];
    raw_entry->args[2] = regs->regs[2];
    raw_entry->args[3] = regs->regs[3];
    raw_entry->args[4] = regs->regs[4];
    raw_entry->args[5] = regs->regs[5];

    trace_buffer_commit(data, file->event, entry, sizeof(*raw_entry), flags, preemption);
}

void handle_syscall_entry(void *data, struct pt_regs *regs, long id) {
    int syscall_num = regs->orig_ax;
    struct ftrace_event_file *event_file;
    struct trace_entry *entry;
    unsigned long flags, pc;

    if (syscall_num < 0 || syscall_num >= __NR_syscalls)
        return;

    event_file = get_syscall_event_file(id);
    if (!event_file || !event_file->enabled)
        return;

    flags = arch_local_save_flags();
    pc = preempt_count();

    entry = trace_buffer_reserve(data, event_file, sizeof(*entry));
    if (!entry)
        return;

    entry->type = TRACE_SYSCALL_ENTRY;
    entry->syscall_id = id;
    entry->args = regs->di;
    entry->args = regs->si;
    entry->args = regs->dx;
    entry->args = regs->cx;
    entry->args = regs->r8;
    entry->args = regs->r9;

    trace_buffer_commit(data, entry, sizeof(*entry), flags, pc);
}

void handle_syscall_entry(void *data, struct pt_regs *regs, long id) {
    int syscall_num = regs->ax;
    struct ftrace_event_file *file = id_to_event_file(syscall_num);
    if (!file || !ftrace_event_enabled(file))
        return;

    struct trace_entry *entry;
    struct ring_buffer *buffer = data;
    unsigned long flags = preempt_count();
    unsigned long irq_flags = local_irq_save();

    entry = ring_buffer_reserve(buffer, sizeof(struct trace_entry));
    if (!entry)
        goto out;

    entry->type = TRACE_SYSCALL_ENTRY;
    entry->nr = syscall_num;

    int i;
    for (i = 0; i < 6; ++i)
        entry->args[i] = regs->di + i;

    ring_buffer_commit(buffer, entry);

out:
    local_irq_restore(irq_flags);
}
